public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize the minimum time required to collect all apples and return to node 0
    int minTime = 0;

    // Create a graph with n nodes and edges
    Graph graph = new Graph(n, edges);

    // Perform a depth-first search starting from node 0
    int[] visited = new int[n];
    int[] parent = new int[n];
    int[] distance = new int[n];
    dfs(graph, 0, visited, parent, distance);

    // Iterate through the nodes and calculate the minimum time required to collect all apples
    for (int i = 0; i < n; i++) {
        if (hasApple[i]) {
            minTime += distance[i];
        }
    }

    return minTime;
}

private void dfs(Graph graph, int node, int[] visited, int[] parent, int[] distance) {
    // Mark the current node as visited
    visited[node] = 1;

    // Update the distance of the current node from the starting node
    distance[node] = distance[parent[node]] + 1;

    // Iterate through the neighbors of the current node
    for (int neighbor : graph.neighbors(node)) {
        if (visited[neighbor] == 0) {
            // Mark the neighbor as visited
            visited[neighbor] = 1;

            // Update the distance of the neighbor from the starting node
            distance[neighbor] = distance[node] + 1;

            // Recursively call dfs for the neighbor
            dfs(graph, neighbor, visited, parent, distance);
        }
    }
}

